import type { APIRequestContext } from "@playwright/test";
import { expect, test, uniqueName } from "../../fixtures";

const TAG = "@VEN-05";
const W9 = "Legal Name: Acme Freight LLC\nTax ID: 12-3456789\nBusiness Type: LLC\n";
const CONTRACT = "Counterparty: Acme Freight LLC\nEffective Date: 2026-01-01\nExpiry Date: 2027-12-31\n";
const INSURANCE = "Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: 2099-12-31\n";

type VendorRow = { id: string; name: string; status: string };
type Page = { items: VendorRow[]; total: number; limit: number; offset: number };

async function createVendor(member: APIRequestContext, name: string): Promise<{ id: string }> {
  const res = await member.post("/api/vendors", {
    data: { name, category: "logistics", contact_email: "ops@acme.example" },
  });
  expect(res.status(), await res.text()).toBe(201);
  return (await res.json()) as { id: string };
}

async function uploadDocuments(member: APIRequestContext, vendorId: string): Promise<void> {
  const docs = [
    ["w9", W9],
    ["insurance_certificate", INSURANCE],
    ["contract", CONTRACT],
  ] as const;
  for (const [kind, text] of docs) {
    const res = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: { kind, file: { name: "doc.txt", mimeType: "text/plain", buffer: Buffer.from(text) } },
    });
    expect(res.status(), await res.text()).toBe(201);
  }
}

async function approvedVendor(member: APIRequestContext, reviewer: APIRequestContext, name: string) {
  const vendor = await createVendor(member, name);
  await uploadDocuments(member, vendor.id);
  // Extraction runs in the background; submit requires every document to be extracted.
  await expect
    .poll(
      async () => {
        const docs = (await (await member.get(`/api/vendors/${vendor.id}/documents`)).json()) as { status: string }[];
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 60_000 },
    )
    .toBe(true);
  const submit = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submit.status(), await submit.text()).toBe(200);
  const docs = (await (await member.get(`/api/vendors/${vendor.id}/documents`)).json()) as { id: string }[];
  for (const doc of docs) {
    const ext = (await (await member.get(`/api/documents/${doc.id}/extraction`)).json()) as { id: string };
    const decision = await reviewer.post(`/api/extractions/${ext.id}/decision`, { data: { decision: "approve" } });
    expect(decision.status(), await decision.text()).toBe(200);
  }
  await expect
    .poll(async () => ((await (await member.get(`/api/vendors/${vendor.id}`)).json()) as VendorRow).status)
    .toBe("approved");
  return vendor;
}

test("list vendors with status filter, pagination, and search", { tag: TAG }, async ({ apiAs }) => {
  test.setTimeout(180_000);
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const run = uniqueName("Listing");

  // Arrange: 25 vendors in the member's tenant, 5 of them approved.
  const approved = await Promise.all(
    [0, 1, 2, 3, 4].map((i) => approvedVendor(member, reviewer, `${run} Freight ${i}`)),
  );
  await Promise.all(Array.from({ length: 20 }, (_, i) => createVendor(member, `${run} Draft ${i}`)));

  const list = async (params: Record<string, string | number>): Promise<Page> => {
    const res = await member.get("/api/vendors", { params });
    expect(res.status(), await res.text()).toBe(200);
    return (await res.json()) as Page;
  };

  // Status filter: 5 approved, total 5.
  const approvedPage = await list({ q: run, status: "approved" });
  expect(approvedPage.items.length, "approved vendors returned").toBe(5);
  expect(approvedPage.total, "approved total").toBe(5);
  expect(approvedPage.items.every((v) => v.status === "approved")).toBe(true);
  expect(approvedPage.items.map((v) => v.id).sort()).toEqual(approved.map((v) => v.id).sort());

  // Pagination: all 25 counted, last page holds the remaining 5.
  const firstPage = await list({ q: run, limit: 1 });
  expect(firstPage.total, "total vendors").toBe(25);
  const lastPage = await list({ q: run, limit: 10, offset: 20 });
  expect(lastPage.items.length, "last page size").toBe(5);
  expect(lastPage.total, "total on last page").toBe(25);

  // Search: every returned name contains the term, ignoring case.
  const freight = await list({ q: "freight", limit: 100 });
  expect(freight.items.length).toBeGreaterThan(0);
  for (const v of freight.items) {
    expect(v.name.toLowerCase(), v.name).toContain("freight");
  }
  const scopedFreight = await list({ q: `${run} freight` });
  expect(scopedFreight.total, "freight vendors in this run").toBe(5);
});
